#include <stdio.h>

int main(void) {
    char *row[4] = {"甲", "乙", "丙", "丁"};
    char *other[4] = {"{a}", "{b}", "{c}", "{d}"};

    for (int i = 0; i < 4; i++) {
        row[i] = other[i];
    }

    for (int i = 0; i < 4; i++) {
        printf("%d: %s\n", i, row[i]);
    }

    return 0;
}
